import { storeToken } from "./pairing-storage";

const PAIRING_DIALOG_URL = "https://localhost:48766/pairing.html";

/**
 * Opens the pairing dialog (pairing.html, served by Companion per D7) and resolves once the
 * user has entered a code and it's been stored, or the dialog was closed without one.
 */
export function showPairingDialog(): Promise<string | null> {
  return new Promise((resolve) => {
    Office.context.ui.displayDialogAsync(
      PAIRING_DIALOG_URL,
      { height: 30, width: 30, displayInIframe: false },
      (asyncResult) => {
        if (asyncResult.status === Office.AsyncResultStatus.Failed) {
          resolve(null);
          return;
        }

        const dialog = asyncResult.value;
        let settled = false;

        const finish = (token: string | null) => {
          if (settled) {
            return;
          }
          settled = true;
          dialog.close();
          resolve(token);
        };

        dialog.addEventHandler(Office.EventType.DialogMessageReceived, (arg) => {
          const message = (arg as Office.DialogParentMessageReceivedEventArgs).message;
          if (message) {
            storeToken(message);
            finish(message);
          } else {
            finish(null);
          }
        });

        dialog.addEventHandler(Office.EventType.DialogEventReceived, () => finish(null));
      },
    );
  });
}
