import { saveAttachments, saveText, openOptions, AttachmentPayload } from "../shared/api";
import { showNotice } from "../shared/notice-dialog";

Office.onReady();

function showHint(item: Office.Item | undefined, message: string): void {
  try {
    // "as any" — item.notificationMessages exists on the Read/Compose surfaces this file
    // targets, but Office.Item's base type doesn't expose it.
    (item as any)?.notificationMessages?.replaceAsync("favorik-hint", {
      type: Office.MailboxEnums.ItemNotificationMessageType.InformationalMessage,
      message,
      icon: "icon-attachment-16",
      persistent: false,
    });
  } catch {
    // Best effort — a missing hint isn't worth failing the whole command over.
  }
}

function getAttachmentDetailsAsync(item: Office.Item): Promise<Office.AttachmentDetails[]> {
  return new Promise((resolve, reject) => {
    (item as any).getAttachmentsAsync((result: Office.AsyncResult<Office.AttachmentDetails[]>) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        resolve(result.value);
      } else {
        reject(result.error);
      }
    });
  });
}

function getAttachmentContentAsync(item: Office.Item, id: string): Promise<Office.AttachmentContent> {
  return new Promise((resolve, reject) => {
    (item as any).getAttachmentContentAsync(id, (result: Office.AsyncResult<Office.AttachmentContent>) => {
      if (result.status === Office.AsyncResultStatus.Succeeded) {
        resolve(result.value);
      } else {
        reject(result.error);
      }
    });
  });
}

/** §3.2/F15: exclude inline attachments (signature images, embedded content) — only real
 * file attachments get saved. */
async function getNonInlineAttachmentsAsBase64(item: Office.Item): Promise<AttachmentPayload[]> {
  const details = await getAttachmentDetailsAsync(item);
  const nonInline = details.filter((a) => !a.isInline);

  const payloads: AttachmentPayload[] = [];
  for (const attachment of nonInline) {
    const content = await getAttachmentContentAsync(item, attachment.id);
    if (content.format === Office.MailboxEnums.AttachmentContentFormat.Base64) {
      payloads.push({ name: attachment.name, isInline: attachment.isInline, contentBase64: content.content });
    }
  }
  return payloads;
}

/** Office.js's MessageRead surface exposes `dateTimeCreated`, the closest analog to legacy's
 * mailItem.ReceivedTime — there's no dedicated "received time" property on the item model. */
function getReceivedTimeIso(item: Office.Item | undefined): string | null {
  const created = (item as any)?.dateTimeCreated;
  return created instanceof Date ? created.toISOString() : null;
}

Office.actions.associate("favorikSave", async (event: Office.AddinCommands.Event) => {
  try {
    const item = Office.context.mailbox.item;
    if (!item) {
      // D1: multi-select is dropped. The same button also surfaces in Outlook's multi-select
      // toolbar (Mailbox 1.13+); there's no single resolvable item in that context, which is how
      // this is detected at runtime rather than via a separate manifest extension point — Outlook
      // add-in manifests don't have a distinct "multi-select" surface, buttons on
      // MessageReadCommandSurface are automatically also offered there. NOTE: this branch needs
      // manual verification against a live multi-select click — flagged upfront as something my
      // tools can't drive. No resolvable item means notificationMessages has nothing to attach
      // to, so this uses a dialog instead.
      await showNotice("Please select only one email.");
      event.completed();
      return;
    }

    const attachments = await getNonInlineAttachmentsAsBase64(item);
    const result = await saveAttachments((item as any).subject ?? null, getReceivedTimeIso(item), attachments);
    if (!result.success) {
      showHint(item, result.message);
    }
  } catch (error) {
    showHint(Office.context.mailbox.item, `Favorik: ${String(error)}`);
  } finally {
    event.completed();
  }
});

Office.actions.associate("saveText", async (event: Office.AddinCommands.Event) => {
  try {
    const item = Office.context.mailbox.item;
    // D6 (ribbon path): Companion's Save Text flow never reads clipboard content over the API —
    // legacy's auto-paste was already dead code and isn't resurrected (§4.2) — the user pastes
    // manually into the notes file Companion opens. This hint is the cue to copy first.
    showHint(item, "Press Ctrl+C on your selection first, then continue.");
    await saveText((item as any)?.subject ?? null, getReceivedTimeIso(item));
  } catch (error) {
    showHint(Office.context.mailbox.item, `Favorik: ${String(error)}`);
  } finally {
    event.completed();
  }
});

Office.actions.associate("openOptions", async (event: Office.AddinCommands.Event) => {
  try {
    await openOptions();
  } catch (error) {
    showHint(Office.context.mailbox.item, `Favorik: ${String(error)}`);
  } finally {
    event.completed();
  }
});
