// §1.1: the add-in obtains the Companion's shared secret via a one-time pairing step, stored in
// Office.context.roamingSettings (roams with the signed-in M365 account across the user's
// devices) with a localStorage fallback for hosts/contexts where roamingSettings isn't usable.

const TOKEN_KEY = "favorikCompanionToken";

export function getStoredToken(): string | null {
  try {
    const roaming = Office.context.roamingSettings?.get(TOKEN_KEY);
    if (typeof roaming === "string" && roaming.length > 0) {
      return roaming;
    }
  } catch {
    // roamingSettings can throw in hosts/contexts where it isn't available — fall through.
  }

  try {
    return localStorage.getItem(TOKEN_KEY);
  } catch {
    return null;
  }
}

export function storeToken(token: string): void {
  try {
    localStorage.setItem(TOKEN_KEY, token);
  } catch {
    // Best effort — roamingSettings below is the primary store.
  }

  try {
    Office.context.roamingSettings?.set(TOKEN_KEY, token);
    Office.context.roamingSettings?.saveAsync();
  } catch {
    // Best effort — localStorage above already has it.
  }
}

export function clearStoredToken(): void {
  try {
    localStorage.removeItem(TOKEN_KEY);
  } catch {
    // ignore
  }

  try {
    Office.context.roamingSettings?.remove(TOKEN_KEY);
    Office.context.roamingSettings?.saveAsync();
  } catch {
    // ignore
  }
}
