import { getStoredToken } from "./pairing-storage";
import { showPairingDialog } from "./pairing-dialog";

const COMPANION_BASE_URL = "https://localhost:48766";

export interface AttachmentPayload {
  name: string;
  isInline: boolean;
  contentBase64: string;
}

export interface ApiResult {
  success: boolean;
  message: string;
  folder?: string;
}

async function request(path: string, body?: unknown): Promise<Response> {
  const token = getStoredToken();
  return fetch(`${COMPANION_BASE_URL}${path}`, {
    method: body === undefined ? "GET" : "POST",
    headers: {
      "Content-Type": "application/json",
      ...(token ? { "X-Favorik-Token": token } : {}),
    },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
}

/**
 * Calls the Companion API, transparently pairing (once) if there's no stored token yet or the
 * stored one was rejected (401) — e.g. after the user re-paired on another device, or Companion
 * regenerated its token file. Companion being unreachable at all (offline) surfaces as a normal
 * network-error rejection, distinct from an auth failure.
 */
async function callWithPairing(path: string, body?: unknown): Promise<Response> {
  if (!getStoredToken()) {
    await showPairingDialog();
  }

  let response = await request(path, body);
  if (response.status === 401) {
    await showPairingDialog();
    response = await request(path, body);
  }

  return response;
}

export async function ping(): Promise<boolean> {
  try {
    const response = await request("/api/ping");
    return response.ok;
  } catch {
    return false;
  }
}

/**
 * 401 (pairing rejected/cancelled) and 403 (disallowed origin) responses have no JSON body —
 * only successful Companion handlers return an ApiResult shape — so those must be turned into a
 * synthetic result here rather than handed to response.json(), which would throw on the empty
 * body and surface as a confusing "Unexpected end of JSON input" error to the user.
 */
async function parseApiResult(response: Response): Promise<ApiResult> {
  if (response.status === 401) {
    return { success: false, message: "Pairing with Favorik Companion was not completed." };
  }
  if (response.status === 403) {
    return { success: false, message: "Favorik Companion rejected this request's origin." };
  }
  if (!response.ok) {
    return { success: false, message: `Favorik Companion returned an unexpected error (${response.status}).` };
  }
  return (await response.json()) as ApiResult;
}

export async function saveAttachments(
  subject: string | null,
  receivedTime: string | null,
  attachments: AttachmentPayload[],
): Promise<ApiResult> {
  const response = await callWithPairing("/api/save-attachments", { subject, receivedTime, attachments });
  return parseApiResult(response);
}

export async function saveText(subject: string | null, receivedTime: string | null): Promise<ApiResult> {
  const response = await callWithPairing("/api/save-text", { subject, receivedTime });
  return parseApiResult(response);
}

export async function openOptions(): Promise<ApiResult> {
  const response = await callWithPairing("/api/open-options");
  return parseApiResult(response);
}
